SELECT c.id, c.blog_id, c.user_id, c.parent_id, c.reply_user_id, c.content, c.status, (SELECT COUNT(*) FROM tb_user_like ul WHERE ul.target_type = 'comment' AND ul.target_id = c.id AND ul.status = 1 AND ul.deleted = 0) AS like_count, c.create_time, c.update_time, c.deleted FROM tb_comment c LEFT JOIN tb_user u ON c.user_id = u.id WHERE c.deleted = 0
AND c.blog_id = #{blogId}
AND c.status = #{status}
AND ( c.content LIKE CONCAT('%', #{keyword}, '%') OR u.username LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY c.create_time DESC

SELECT c.id, c.blog_id, c.user_id, c.parent_id, c.reply_user_id, c.content, c.status, (SELECT COUNT(*) FROM tb_user_like ul WHERE ul.target_type = 'comment' AND ul.target_id = c.id AND ul.status = 1 AND ul.deleted = 0) AS like_count, c.create_time, c.update_time, c.deleted FROM tb_comment c WHERE c.deleted = 0 AND (c.parent_id IS NULL OR c.parent_id = 0)
AND c.blog_id = #{blogId}
AND c.status = #{status}
ORDER BY c.create_time DESC
